import{c as e,S as l,j as r,m as i}from"./chunks/framework.8aa1YH_s.js";const u=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 16: Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler","description":"","frontmatter":{},"headers":[],"relativePath":"16 Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler.md","filePath":"16 Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler.md"}'),n={name:"16 Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler.md"};function t(m,a,s,o,g,d){return l(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="turk-dil-bilgisi-serisi-16-kelime-turleri-edatlar-baglaclar-ve-unlemler" tabindex="-1">Türk Dil Bilgisi Serisi - 16: Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler <a class="header-anchor" href="#turk-dil-bilgisi-serisi-16-kelime-turleri-edatlar-baglaclar-ve-unlemler" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 16: Kelime Türleri - Edatlar, Bağlaçlar ve Ünlemler”">​</a></h1><p>Kelime türleri serimizde tek başına anlamı olan ve dünyayı anlamlandırmamızı sağlayan ana türleri geride bıraktık. Bu yazımızda ise tek başlarına sözlük anlamı taşımayan, ancak cümle içinde kelimeler arasında köprü kuran, cümleleri birbirine bağlayan ya da dile duygu tonu katan <strong>Edatlar, Bağlaçlar ve Ünlemler</strong> konusunu ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin’e göre bu kelime grupları yardımcı unsurlardır. Kendilerinden önceki veya sonraki kelimelerle birleşerek dildeki ilişkiler ağını örerler.</p><hr><h2 id="_1-edatlar-ilgecler" tabindex="-1">1. Edatlar (İlgeçler) <a class="header-anchor" href="#_1-edatlar-ilgecler" aria-label="Permalink to “1. Edatlar (İlgeçler)”">​</a></h2><p>Tek başlarına anlamları olmayan, kendinden önceki isim soylu kelimelerle birleşerek cümle içinde yön, zaman, araç, sebep, benzerlik veya birliktelik gibi anlam ilgileri kuran kelimelerdir.</p><p>Muharrem Ergin sistematiğinde edatların en büyük özelliği, <strong>kendisinden önceki isme hal ekleriyle (<code>-e, -den</code>) bağlanarak bir &quot;Edat Grubu&quot; oluşturmalarıdır</strong>.</p><h3 id="en-sık-kullanılan-edatlar-ve-kattıgı-anlamlar" tabindex="-1">En Sık Kullanılan Edatlar ve Kattığı Anlamlar: <a class="header-anchor" href="#en-sık-kullanılan-edatlar-ve-kattıgı-anlamlar" aria-label="Permalink to “En Sık Kullanılan Edatlar ve Kattığı Anlamlar:”">​</a></h3><ul><li><strong>Gibi (Benzerlik):</strong> Cennet <strong>gibi</strong> vatan.</li><li><strong>İle / -le (Araç, Birliktelik):</strong> Ankara&#39;ya uçak <strong>ile</strong> (uçakla) gittim. Ahmet <strong>ile</strong> çalıştık.</li><li><strong>İçin (Amaç, Sebep):</strong> Seni görmek <strong>için</strong> geldim. Bizim <strong>için</strong> fark etmez.</li><li><strong>Kadar (Ölçü, Karşılaştırma):</strong> Dev <strong>kadar</strong> bir adam.</li><li><strong>Doğru (-e doğru / Yönelme):</strong> Eve <strong>doğru</strong> yürüdü.</li><li><strong>Beri (-den beri / Zaman başlangıcı):</strong> Sabahtan <strong>beri</strong> kod yazıyorum.</li><li><strong>Başka (-den başka / İstisna):</strong> Senden <strong>başka</strong> kimsem yok.</li></ul><hr><h2 id="_2-baglaclar" tabindex="-1">2. Bağlaçlar <a class="header-anchor" href="#_2-baglaclar" aria-label="Permalink to “2. Bağlaçlar”">​</a></h2><p>Edatlar gibi tek başlarına anlamları yoktur; ancak edatlardan çok önemli bir farkla ayrılırlar. Edatlar kelimeler arasında anlam ilişkisi kurarken, bağlaçlar <strong>eş görevli kelimeleri, kelime gruplarını veya bağımsız cümleleri birbirine bağlama</strong> görevi üstlenirler.</p><p>Bağlaçlar cümleden çıkarıldığında cümlenin anlamı daralabilir ama genellikle yapısı tamamen bozulmaz (Edatlarda ise cümle yapısı altüst olur).</p><h3 id="en-sık-kullanılan-baglaclar" tabindex="-1">En Sık Kullanılan Bağlaçlar: <a class="header-anchor" href="#en-sık-kullanılan-baglaclar" aria-label="Permalink to “En Sık Kullanılan Bağlaçlar:”">​</a></h3><ul><li><strong>Ve / İle:</strong> İki unsuru eşit şekilde bağlar. (<em>Ali <strong>ve</strong> Ahmet geldiler.</em>)</li><li><strong>Veya / Ya da / Yahut:</strong> Seçenek sunar. (<em>Mavi <strong>veya</strong> kırmızı rengi seç.</em>)</li><li><strong>Ama / Fakat / Lakin / Ancak:</strong> Karşıtlık bildirir, düşüncenin yönünü değiştirir. (<em>Çok çalıştı <strong>ama</strong> projeyi yetiştiremedi.</em>)</li><li><strong>Çünkü / Zira:</strong> Sebep açıklar. (<em>Gelemedim <strong>çünkü</strong> işim vardı.</em>)</li><li><strong>Da / De:</strong> Eşitlik, katılma, pekiştirme bildirir. Her zaman ayrı yazılır. (<em>Sen <strong>de</strong> bizimle gel.</em>)</li><li><strong>Ki:</strong> Cümleleri birbirine bağlayan kalıplaşmış bir bağlaçtır. Ayrı yazılır. (<em>Anladım <strong>ki</strong> her şey yalanmış.</em>)</li><li><strong>Hem... Hem... / Ne... Ne... (Tekrarlı Bağlaçlar):</strong> (* <strong>Hem</strong> suçlu <strong>hem</strong> güçlü. <strong>Ne</strong> aradı <strong>ne</strong> sordu.*)</li></ul><hr><h2 id="_3-unlemler" tabindex="-1">3. Ünlemler <a class="header-anchor" href="#_3-unlemler" aria-label="Permalink to “3. Ünlemler”">​</a></h2><p>Tek başlarına doğrudan somut bir anlam taşımayan; ancak korku, sevinç, şaşkınlık, heyecan, acı, öfke gibi <strong>ani ve güçlü duyguları</strong> dışa vuran ya da <strong>seslenme, çağırma, hitap</strong> amacı taşıyan kelimelerdir.</p><p>Muharrem Ergin ünlemleri iki gruba ayırır:</p><h3 id="a-asıl-unlemler" tabindex="-1">A) Asıl Ünlemler <a class="header-anchor" href="#a-asıl-unlemler" aria-label="Permalink to “A) Asıl Ünlemler”">​</a></h3><p>Doğrudan doğruya duygu veya seslenme ifadesi olarak doğmuş kelimelerdir.</p><ul><li><strong>Duygu Ünlemleri:</strong> <em>Ah!, Oh!, Vah vah!, Heyhat!, Aa!, Ooo!, Hay canına!</em></li><li><strong>Seslenme Ünlemleri:</strong> <em>Hey!, Şşt!, Ey!, Yahu!, Bre!</em></li></ul><h3 id="b-unlemlesmis-kelimeler" tabindex="-1">B) Ünlemleşmiş Kelimeler <a class="header-anchor" href="#b-unlemlesmis-kelimeler" aria-label="Permalink to “B) Ünlemleşmiş Kelimeler”">​</a></h3><p>Aslında isim, sıfat veya fiil oldukları halde, vurgu ve tonlama yoluyla cümle içinde birer ünlem gibi kullanılan kelimelerdir.</p><ul><li><em>Örnekler:</em> <strong>Garson!</strong> bakar mısın? / <strong>Arkadaşlar!</strong> beni dinleyin. / <strong>Dur!</strong> geçme.</li></ul><hr><h2 id="ozet-edat-ve-baglacı-ayırt-etme-formulu" tabindex="-1">Özet: Edat ve Bağlacı Ayırt Etme Formülü <a class="header-anchor" href="#ozet-edat-ve-baglacı-ayırt-etme-formulu" aria-label="Permalink to “Özet: Edat ve Bağlacı Ayırt Etme Formülü”">​</a></h2><p>Blog okuyucularının en çok karıştırdığı iki türü ayırmak için Muharrem Ergin mantığına dayanan şu altın kuralı aklımızda tutalım:</p><ol><li><strong>&quot;İle&quot; Kelimesi:</strong> Yerine <strong>&quot;ve&quot;</strong> koyabiliyorsak <strong>bağlaçtır</strong>; koyamıyorsak <strong>edattır</strong>. <ul><li><em>Ali ile Veli geldi.</em> $$\\rightarrow$$Ali <strong>ve</strong> Veli geldi. (Uyar$$\\rightarrow$$ <strong>Bağlaç</strong>)</li><li><em>Arabayla (Araba ile) geldim.</em> $$\\rightarrow$$Araba <strong>ve</strong> geldim. (Uymaz$$\\rightarrow$$ <strong>Edat</strong>)</li></ul></li><li><strong>Çıkarma Testi:</strong> Bağlaç cümleden çıkınca anlam bozulmaz, hafif daralır. Edat çıkınca cümle tamamen çöker veya bambaşka bir şey olur.</li></ol>',29)])])}const b=e(n,[["render",t]]);export{u as __pageData,b as default};
